    S = list(readline())
    ans = []

    def solve(days):
        cnt = 0
        last_worked = -1
        for i in range(N):
            if S[i] == 'x':
                continue
            if i in days:
                if last_worked != -1 and i <= last_worked + C:
                    return False
                cnt += 1
                last_worked = i
        return cnt == K

    possible_days = []
    for i in range(1 << N):
        days = []
        count = 0
        for j in range(N):
            if (i >> j) & 1:
                days.append(j)
                count += 1
        if count == K:
            valid = True
            last_worked = -1
            for day in days:
                if S[day] == 'x':
                    valid = False
                    break
                if last_worked != -1 and day <= last_worked + C:
                    valid = False
                    break
                last_worked = day
            if valid:
                possible_days.append(set(days))

    if not possible_days:
        pass
    else:
        bound_to_work = set()
        for i in range(N):
            is_bound = True
            for possible_day_set in possible_days:
                if i not in possible_day_set:
                    is_bound = False
                    break
            if is_bound and S[i] == 'o':
                bound_to_work.add(i + 1)

        for day in sorted(list(bound_to_work)):
            print(day)

