def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def prime_factorization(n):
    factors = set()
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

