        if bin(i).count('1') > k:
            continue

        cur_v = v[:]
        hand = []
        ops = []

        for j in range(2 * n):
            if (i >> j) & 1:
                ops.append(j)


        cur_ops_count = 0

        for op_index in range(len(ops)):

            op_type = ops[op_index]
            if cur_ops_count >=k:
                break

            if op_type < n:
                if len(cur_v) > 0:
                    hand.append(cur_v.pop(0))
                    cur_ops_count+=1
            else:
                if len(cur_v) > 0:
                    hand.append(cur_v.pop())
                    cur_ops_count+=1




        remaining_ops = k - cur_ops_count

        for j in range(1 << (remaining_ops * 2)):
            temp_hand = hand[:]
            temp_cur_v = cur_v[:]
            temp_ops_count = cur_ops_count

            temp_ans = 0

