def solve(n, s, l):
    if len(s) == n:

        def is_isomorphic(s1, s2):
            if len(s1) != len(s2):
                return False
            map1 = {}
            map2 = {}
            for i in range(len(s1)):
                c1 = s1[i]
                c2 = s2[i]
                if c1 not in map1:
                    map1[c1] = c2
                if c2 not in map2:
                    map2[c2] = c1
                if map1[c1] != c2 or map2[c2] != c1:
                    return False
            return True

        def is_normal(s):

            isomorphic_strings = []

            def generate_isomorphic(s, current_string, char_map, used_chars):
                if len(current_string) == len(s):
                    isomorphic_strings.append(current_string)
                    return

                char_s = s[len(current_string)]
                if char_s in char_map:
                    generate_isomorphic(s, current_string + char_map[char_s], char_map, used_chars)
                else:
                    for char in c:
                        if char not in used_chars:
                            new_char_map = char_map.copy()
                            new_char_map[char_s] = char
                            generate_isomorphic(s, current_string + char, new_char_map, used_chars | {char})

            generate_isomorphic(s, "", {}, set())

            for iso_string in isomorphic_strings:
                if s > iso_string:
                    return False
            return True

        if is_normal(s):
            l.append(s)
        return

    for char in c:
        solve(n, s + char, l)
