    x, y = map(int, input().split())
    balls.append((x, y))

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def solve(p, q):
    collected = set()
    cur_p = 0
    cur_q = 0
    cur_cost = 0

    while len(collected) < n:
        next_ball = None
        next_cost = float('inf')
        for i, (x, y) in enumerate(balls):
            if (x - cur_p, y - cur_q) not in collected:
                cost = abs(p * (x - cur_p) + q * (y - cur_q))
                if cost < next_cost:
                    next_cost = cost
                    next_ball = i

        collected.add((balls[next_ball][0] - cur_p, balls[next_ball][1] - cur_q))
        cur_p = balls[next_ball][0]
        cur_q = balls[next_ball][1]
        cur_cost += next_cost

    return cur_cost

