    """n を素因数分解した時の 2 の指数
    """
    s = 0
    while n % 2 == 0:
        s += 1
        n //= 2
    return s


def multiple3_or_divide2(N: int, A: list) -> int:
    return sum(num2(a) for a in A)



def multiple3_or_divide2(N: int, A: list) -> int:
    total_operations = sum(num2(a) for a in A)
    odd_count = sum(1 for a in A if a % 2 != 0)
    return total_operations - odd_count

