from math import gcd

def solve():
    import sys
    input = sys.stdin.readline
    a, b = list(map(int, input().rstrip('\n').split()))

    def prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    g = gcd(a, b)
    pf = prime_factors(g)

