def resolve():
    N, K = [int(item) for item in input().split()]
    R, S, P = [int(item) for item in input().split()]
    T = input()

    max_point = 0
    last_moves = [''] * K

    for i in range(N):
        machine_move = T[i]

        # Determine what move Takahashi can play
        if i < K:
            possible_moves = ['r', 'p', 's']
        else:
            possible_moves = ['r', 'p', 's']
            possible_moves.remove(last_moves[i % K])

        # Calculate scores for possible moves
        scores = { 'r': 0, 'p': 0, 's': 0 }
        if machine_move == 'r':
            scores['p'] = P
        elif machine_move == 'p':
            scores['r'] = R
        elif machine_move == 's':
            scores['s'] = S

        # Find the best move
        best_move = max(possible_moves, key=lambda x: scores[x])
        max_point += scores[best_move]

        # Update last moves array
        last_moves[i % K] = best_move

    print(max_point)

