M,K = map(int, input().split())


def construct_sequence(M, K):
    n = 2 ** (M + 1)
    sequence = []

    for i in range(2 ** M):
        sequence.append(i)
        sequence.append(i)

    ranges = [[] for _ in range(2 ** M)]

    idx = 0
    for num in sequence:
        ranges[num].append(idx)
        idx += 1

    for indices in ranges:
        if len(indices) == 2:
            if (indices[0] + 1 >= indices[1]) or (sequence[indices[0]:indices[1] + 1].count(sequence[indices[0]]) % 2 != K % 2):
                return [-1]

    return sequence

M, K = map(int, input().split())
result = construct_sequence(M, K)
print(*result)

