from bisect import bisect_left

def mix(abc,Ma,Mb):
    n = len(abc)
    OP = []
    for i in range(2**n):
        i_bin = bin(i)[2:]
        if len(i_bin) < n:
            pad = "0" * (n-len(i_bin))
            i_bin = pad + i_bin
        a,b,c = 0,0,0
        for j in range(len(i_bin)):
            if i_bin[j] == "1":
                a += abc[j][0]
                b += abc[j][1]
                c += abc[j][2]
        d = Mb*a-Ma*b
        OP.append((d,c))
    OP.sort(key = lambda x:x[0])
    return OP

def main():
    N,Ma,Mb = map(int,input().split())
    abc = [list(map(int,input().split())) for _ in range(N)]
    INF = 4001

    abc1,abc2 = abc[:len(abc)//2],abc[len(abc)//2:]
    DC1,DC2 = mix(abc1,Ma,Mb),mix(abc2,Ma,Mb)
    D2 = [DC2[i][0] for i in range(len(DC2))]
    D2_set = set(D2)

    ans = INF
    for i in range(len(DC1)):
        d1,c1 = DC1[i][0],DC1[i][1]
        if -d1 in D2_set:
            ind = bisect_left(D2,-d1)
            c2 = DC2[ind][1]
            if c1 + c2 > 0:
                ans = min(ans,c1+c2)
    if len(DC1) == 0:
        if DC2[0][0] == 0:
            ans = DC2[0][1]

    if ans != INF:
        print(ans)
    else:
        print(-1)


if __name__ == "__main__":
    main()

