h,w,k = map(int,input().split())
s = [list(map(int,input().strip())) for i in range(h)]
from copy import deepcopy

ss = deepcopy(s)
for i in range(h):
    for j in range(w-1):
        ss[i][j+1] += ss[i][j]


def gru_hol(HOL): # セットから切り方を作る
    groups_a = []
    group_a = [0]
    for i in range(h-1):
        if(HOL[i] == 1):
            groups_a.append(group_a)
            group_a = [i+1]
        else:
            group_a.append(i+1)
    groups_a.append(group_a)
    return groups_a

def nex_hol(HOL): #次のセットを作る
    for j in range(h-1):
        if(HOL[j] == 0):
            HOL[j] = 1
            for k in range(0,j):
                HOL[k] = 0
            break
    return HOL

def cutsum(grp,lscut,nxcut): #groupのlastcut~nextcutのホワイトチョコを数える
    count = 0
    for i in grp:
        if(lscut != 0):
            count = count + ss[i][nxcut-1] - ss[i][lscut-1]
        else:
            count += ss[i][nxcut-1] 
    return count

def cutcheck(grp_a,lscut_a): #切ってもダメかチェック
    ct_a = 0
    for i in grp_a:
        ct_a += s[i][lscut_a]
    if(ct_a > k):
        return False
    else:
        return True

min_cut = h + w - 2
hol = [0]*(h-1)

while True:
    if sum(hol) == 0:  # All rows are cut
        break
    for i in range(len(hol)):
        if hol[i] == 0:
            lscut = i
            if cutcheck(gru_hol(hol), lscut):
                continue
            else:
                min_cut = min(min_cut, sum(hol) + 1)
                hol[i] = 1
                hol = nex_hol(hol)
                break
        if i == len(hol) - 1:
            hol = nex_hol(hol)

for j in range(w-1):
    if sum(hol) == 0:  # All cuts done
        break
    ct = cutsum(gru_hol(hol), 0, j)
    if ct > k:
        if cutcheck(gru_hol(hol), j):
            continue
        else:
            min_cut += 1
            hol[j] = 1
            hol = nex_hol(hol)



print(min_cut)

