def dfs(index, current):
    if index == N:
        return current
    total = 0
    total += dfs(index + 1, current * 10 + int(S[index]))  # continue the current number
    if index < N - 1:
        total += dfs(index + 1, int(S[index]))  # start a new number with a '+'
    return total

# Start the recursion with the first digit
