def calculate_arrival_times(n, a):
    result = [0] * (n + 1)

    for i in range(n - 1, -1, -1):
        if i == n - 1:
            result[i + 1] = 0
        else:
            C_i, S_i, F_i = a[i]
            time_to_next_station = result[i + 1]
            # Determine the time to catch the next train at station i
            if time_to_next_station <= S_i:
                departure_time = S_i
            else:
                departure_time = S_i + ((time_to_next_station - S_i + F_i - 1) // F_i) * F_i

            # Calculate arrival time at next station
            result[i] = departure_time + C_i

    return result[1:]

n = int(input())
