def min_insertions_to_palindrome(s):
    def is_palindrome(s):
        return s == s[::-1]

    def count_insertions(s):
        left, right = 0, len(s) - 1
        insertions = 0
        while left < right:
            if s[left] == s[right]:
                left += 1
                right -= 1
            else:
                insertions += 1
                # We can either insert s[left] next to s[right] or vice versa by skipping a character
                if s[left] < s[right]:
                    left += 1
                else:
                    right -= 1
        return insertions

    if is_palindrome(s):
        return 0
    return count_insertions(s)

