def lcm(x, y):
    return x * y // gcd(x, y)

def find_min_votes(n, ratios):
    votes = [1, 1]  # Start with at least 1 vote for each
    for T, A in ratios:
        total_votes = votes[0] + votes[1]
        new_total_votes = lcm(votes[0] * A, votes[1] * T) // (T + A)  # Calculate new total votes
        votes = [new_total_votes * T // A, new_total_votes]  # Update votes based on the ratio
    return sum(votes)

